export const acceptanceScenarios={T01:'부분/과납 승인·반려·품질보류·분할 적치',T02:'동시예약·부족·재입고·명시 재예약',T05:'배송실패·반품 실제도착·재검수',T06:'오스캔·부족·실사승인·파손대체',T07:'중복사건·버튼·응답유실·새키동일실물',T08:'순서역전·누락revision·참조거절·내용충돌',T03:'포장20/21·12+9명세 경계와 전체포장 출하',T04:'미예약·예약·피킹·포장·인계 후 취소',T10:'동일코드 회사격리·창고제한·회수키 차단'};
const extended=new Set(['T01','T02','T05','T06','T07','T08']);
const requiredChecks={T01:['partial_overage_105','overage_approved_separately','quality_hold_preserved','split_putaway','overage_rejected_preserves_physical','unapproved_overage_no_effect','rejected_overage_no_effect','two_storage_locations_used'],T02:['concurrent_reservations_one_winner','shortage_remaining_tracked','explicit_rereservation_after_receipt'],T03:['boundary20','boundary12plus9'],T04:['cancel.unreserved','cancel.reserved','cancel.picked','cancel.packed','cancel.shipped'],T05:['delivery_failure_no_stock','return_request_no_stock','return_actual_arrival_only','partial_return_close_and_inspect'],T06:['wrong_scans_no_effect','shortage_blocks_location','count_approval_only_adjustment','packed_damage_requires_unpack','damage_preserves_physical_and_order','replacement_good_only_shipped'],T07:['external_duplicates_one_object','lost_response_recovered_original','duplicate_receive_same_request','new_request_same_physical_rejected','duplicate_package_and_shipment_no_effect'],T08:['revision_gap_waits','revision_three_one_two_recovers','stale_revision_no_regression','event_content_conflict','revision_content_conflict','invalid_reference_business_rejected','business_rejection_new_revision_recovers','update_before_create_recovers','invalid_envelope_classified'],T10:['key_revocation_next_request','identical_codes_company_and_warehouse_isolation']};
const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
const buckets=['S','R','P','Q','B'];
const fingerprint=value=>createHash('sha256').update(JSON.stringify(value)).digest('hex');
const qty=(item,location,bucket,delta)=>({item_id:item,location_id:location,bucket,delta});
