  for(let i=0;i<120;i++){await call('A','process','/api/v2/integration/process',{warehouse_id:config.warehouse_id,limit:50});const row=await eventState(event);if(row?.status===status){if(reason)ensure(row.reason===reason,'WRONG_EXTERNAL_CLASSIFICATION');store.observe(runId,'external_classification',{label,event_id:event.event_id,status:row.status,reason:row.reason,object_id:row.result?.id??null});return row;}if(['business_rejected','quarantined'].includes(row?.status))throw new HttpFailure(409,row.reason??'WRONG_EXTERNAL_CLASSIFICATION');await pause(100);}
  throw new HttpFailure(503,'EXTERNAL_EVENT_NOT_SETTLED');
