 async function receive(label,receipt,amount,{overage=0,physical=label,loseResponse=false}={}){return command(label,'receipt.receive',{receipt_id:receipt.id,receiving_id:stableId(runId+':physical:'+physical),...(overage?{reason:'Additional physical pieces require isolated acceptance'}:{}),lines:[{line_id:receipt.lines[0].id,quantity:amount,location_id:config.receiving_id,hold_location_id:config.hold_id}]},{loseResponse,deltas:[qty(config.item_id,config.receiving_id,'Q',amount-overage),...(overage?[qty(config.item_id,config.hold_id,'B',overage)]:[])]});}
